mapper.select:
SELECT *
FROM ai_knowledge_document
WHERE organization_id = #{orgId}

    AND (
        name LIKE CONCAT('%', #{request.keyword}, '%')
        OR original_name LIKE CONCAT('%', #{request.keyword}, '%')
        OR remark LIKE CONCAT('%', #{request.keyword}, '%')
    )


    AND file_type = #{request.fileType}


    AND category = #{request.category}


    AND parse_status = #{request.parseStatus}


    AND enabled = #{request.enabled}

ORDER BY update_time DESC

SELECT *
FROM ai_knowledge_chunk
WHERE organization_id = #{orgId}
  AND document_id = #{documentId}
ORDER BY chunk_index ASC

SELECT c.* FROM ai_knowledge_chunk c INNER JOIN ai_knowledge_document d ON d.id = c.document_id WHERE c.organization_id = #{orgId} AND c.enabled = 1 AND d.enabled = 1 AND d.parse_status = 'PARSED' AND ( c.content LIKE CONCAT('%', #{question}, '%')
OR c.content LIKE CONCAT('%', #{keyword}, '%') OR c.title LIKE CONCAT('%', #{keyword}, '%') OR d.name LIKE CONCAT('%', #{keyword}, '%')
) ORDER BY c.update_time DESC LIMIT #{limit}

mapper.delete:
DELETE FROM ai_knowledge_chunk
WHERE organization_id = #{orgId}
  AND document_id = #{documentId}
